-- app_logs table baseline.
--
-- The self-hosted DB already has this table with stricter RLS policies
-- (authenticated_can_insert_logs requires user_id = auth.uid() OR NULL;
-- admins_can_read_logs / admins_can_delete_logs gate on user_roles).
-- This migration was auto-generated by Lovable with a permissive
-- "Anyone can insert logs" policy (WITH CHECK (true)) that would
-- weaken security via PostgreSQL's OR-combine semantics, so this
-- rewrite keeps only the idempotent structural parts and explicitly
-- drops the Lovable-named policies if they ever slipped in.

CREATE TABLE IF NOT EXISTS public.app_logs (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
  category TEXT NOT NULL,
  operation TEXT NOT NULL,
  status TEXT NOT NULL,
  user_id UUID,
  user_email TEXT,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  error_message TEXT,
  duration_ms INTEGER
);

CREATE INDEX IF NOT EXISTS idx_app_logs_created_at ON public.app_logs (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_app_logs_category ON public.app_logs (category);
CREATE INDEX IF NOT EXISTS idx_app_logs_status ON public.app_logs (status);

ALTER TABLE public.app_logs ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Anyone can insert logs" ON public.app_logs;
DROP POLICY IF EXISTS "Admins can view logs" ON public.app_logs;
DROP POLICY IF EXISTS "Admins can delete logs" ON public.app_logs;
